--UNCOMMENT SET DEFINE OFF TO RUN THIS SCRIPT IN SQLPLUS/SQL DEVELOPER

--SET DEFINE OFF

--UNCOMMENT SET SQLBLANKLINES ON TO RUN THIS SCRIPT IN SQLPLUS

--SET SQLBLANKLINES ON

DROP VIEW PS_FLSA_PERIOD_VW
/
CREATE VIEW PS_FLSA_PERIOD_VW (FLSA_PERIOD_TYPE) AS SELECT
 SUBSTR(A.FIELDVALUE, 1, 2) FROM PSXLATITEM A WHERE FIELDNAME =
 'FLSA_PERIOD_TYPE' AND EFF_STATUS = 'A' AND A.EFFDT=(SELECT
 MAX(EFFDT) FROM PSXLATITEM PSXLATITEM WHERE
 PSXLATITEM.FIELDNAME=A.FIELDNAME AND
 PSXLATITEM.FIELDVALUE=A.FIELDVALUE AND
 PSXLATITEM.EFFDT<=TO_DATE(TO_CHAR(SYSDATE,'YYYY-MM-DD'),'YYYY-MM-DD'))
/